import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

public final class NonPokemonBatch61Test {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B;
    static final List<String> IDS=List.of("swsh3_en_167","swsh4_en_149","swsh4-5_en_067");
    static TrainerProfile trainer(String id){return NonPokemonBatch2Test.DATA.trainer(id).orElseThrow();}
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static CardInstance hand(ServerMatch m,UUID p,String id){return DynamicPassiveModifierTest.hand(m,p,id);}
    static ServerMatch aiGame(String id){return fixture(id);}
    static ServerMatch fixture(String id){return fixture(id,GeneratedRuleBatch8Test.hit(100,false));}
    static ServerMatch fixture(String id,AttackDefinition hit){
        var defs=new ArrayList<CardDefinition>();String[] pattern={"basic","basic","basic","basic","fossil","fossil","energy","evolved","wrong","trainer"};
        for(String key:Arrays.stream(pattern).distinct().toList()){boolean pokemon=key.equals("basic")||key.equals("evolved");defs.add(new CardDefinition(key,key,pokemon?CardCategory.POKEMON:key.equals("energy")?CardCategory.ENERGY:CardCategory.TRAINER,key.equals("trainer")?trainer(id).category():Set.of("fossil","wrong").contains(key)?TrainerCategory.ITEM:TrainerCategory.NONE,"H",Set.of("international"),key.equals("basic"),key.equals("energy"),60,Map.of(),EffectSupport.SUPPORTED,null));}
        var base=new PokemonProfile(500,0,null,null,0,null,0,1,List.of(hit),List.of(),EnergyType.COLORLESS,"Base",null);var evolution=new PokemonProfile(150,0,"fossil",null,0,null,0,1,List.of(hit),List.of(),EnergyType.WATER,"Evolved Fossil","Rare Fossil");
        var combat=new CombatCatalog(Map.of("basic",base,"evolved",evolution),Map.of("energy",EnergyType.COLORLESS),Map.of("trainer",trainer(id),"fossil",trainer(IDS.getFirst()),"wrong",FossilFormTest.fossil()));
        for(int seed=0;seed<500;seed++){var decks=new ArrayList<List<CardInstance>>();for(UUID p:List.of(A,B)){var deck=new ArrayList<CardInstance>();for(int i=0;i<60;i++)deck.add(new CardInstance(new UUID(p.getLeastSignificantBits(),i+1),p,pattern[i%pattern.length]));decks.add(deck);}var m=new ServerMatch(A,B,decks.get(0),decks.get(1),GeneratedRuleBatch8Test.RULES,new CardDatabase(defs),combat,new ServerRandom(seed));OpeningTestSupport.decideOrder(m,A,B);if(List.of(A,B).stream().anyMatch(p->m.privateView(p).hand().stream().filter(c->c.definitionId().equals("basic")).count()<2))continue;OpeningTestSupport.complete(m,A,B,1);m.drawCardsByEffect(A,A,23);m.drawCardsByEffect(A,B,23);m.endTurn(A);m.endTurn(B);if(List.of(A,B).stream().allMatch(p->m.privateView(p).hand().stream().filter(c->c.definitionId().equals("basic")).count()>=4&&List.of("trainer","fossil","evolved","energy").stream().allMatch(k->m.privateView(p).hand().stream().anyMatch(c->c.definitionId().equals(k)))&&m.privateView(p).deck().stream().filter(c->c.definitionId().equals("fossil")).count()>=2&&m.privateView(p).deck().stream().anyMatch(c->c.definitionId().equals("wrong"))))return m;}throw new AssertionError("No Rare Fossil fixture");
    }
    public static void main(String[] args){form();search();knockout();System.out.println("NonPokemonBatch61Test passed: actual 70-HP Rare Fossil Item/form, status immunity despite suppression, retreat prohibition, switching/evolution/devolution, voluntary discard and one-Prize knockout; both Cara Liss printings, both owners, exact named Item filter, zero-to-two placement, full Bench rejection and shuffle");}
    static void form(){for(UUID p:List.of(A,B)){
        var m=fixture(IDS.getFirst());if(p.equals(B))m.endTurn(A);UUID other=p.equals(A)?B:A;var card=hand(m,p,"trainer");m.playTrainer(p,card.instanceId(),null);UUID host=m.benchPokemonView(p).getLast().pokemonId();check(m.benchPokemonView(p).getLast().hitPoints()==70&&m.cardDefinition("trainer").category()==CardCategory.TRAINER&&!m.cardDefinition("trainer").basicPokemon(),"Rare Fossil wrong form/global identity");m.switchActiveByEffect(p,p,host);m.disableAbilityEffectsByEffect(p,p,host);for(var condition:SpecialCondition.values())GeneratedRuleBatch8Test.reject(()->m.applySpecialConditionByEffect(p,p,condition));check(m.activePokemonView(p).conditions().isEmpty(),"Rare Fossil lost printed condition immunity");UUID bench=m.benchPokemonView(p).getFirst().pokemonId();GeneratedRuleBatch8Test.reject(()->m.retreat(p,bench,List.of()));var energy=hand(m,p,"energy");m.attachEnergy(p,energy.instanceId(),host);m.evolveByEffect(p,host,hand(m,p,"evolved").instanceId(),EvolutionPermission.CARD_EFFECT_ALL_TIMING);m.applySpecialConditionByEffect(p,p,SpecialCondition.POISONED);check(m.activePokemonView(p).conditions().contains(SpecialCondition.POISONED)&&!m.canDiscardFossil(p,host),"Evolution retained fossil rules");m.devolvePokemonToHandByEffect(p,p,host);GeneratedRuleBatch8Test.reject(()->m.applySpecialConditionByEffect(p,p,SpecialCondition.BURNED));check(m.activePokemonView(p).conditions().isEmpty()&&m.canDiscardFossil(p,host),"Devolution did not restore fossil rules");int prizes=m.privateView(other).prizes().size();m.discardFossil(p,host);NonPokemonBatch2Test.settle(m);check(m.privateView(p).discard().containsAll(List.of(card,energy))&&m.privateView(other).prizes().size()==prizes,"Voluntary fossil discard lost attachments or awarded Prize");
    }}
    static void search(){for(String id:IDS.subList(1,3))for(UUID p:List.of(A,B))for(int space:List.of(0,1,2,4))for(int requested=0;requested<=2;requested++){
        var m=fixture(id);if(p.equals(B))m.endTurn(A);while(m.benchPokemonView(p).size()<5-space)m.playBasicPokemonToBench(p,hand(m,p,"basic").instanceId());var source=hand(m,p,"trainer");int before=m.benchPokemonView(p).size();check(m.canPlayTrainer(p,source.instanceId(),null)==(space>0),"Cara Liss full Bench eligibility");if(space==0)continue;int rng=m.randomTranscript().size();m.playTrainer(p,source.instanceId(),null);var q=m.effectCardPrompt(p);check(q.minimum()==0&&q.maximum()==Math.min(2,space)&&q.candidates().stream().allMatch(c->c.definitionId().equals("fossil")),"Cara Liss selected wrong Fossil or capacity");var wrong=m.privateView(p).deck().stream().filter(c->c.definitionId().equals("wrong")).findFirst().orElseThrow();GeneratedRuleBatch8Test.reject(()->m.submitEffectCards(p,q.resolutionId(),q.step(),List.of(wrong.instanceId())));var selected=q.candidates().subList(0,Math.min(requested,space));m.submitEffectCards(p,q.resolutionId(),q.step(),selected.stream().map(CardInstance::instanceId).toList());NonPokemonBatch2Test.settle(m);check(m.benchPokemonView(p).size()==before+selected.size()&&m.benchPokemonView(p).stream().filter(v->v.topCardId().equals("fossil")&&v.hitPoints()==70).count()==selected.size(),"Cara Liss failed to place exact selected Items");check(m.randomTranscript().size()>rng&&m.privateView(p).discard().contains(source),"Cara Liss did not shuffle/dispose Supporter");for(var placed:List.copyOf(m.benchPokemonView(p)))if(placed.topCardId().equals("fossil"))m.discardFossil(p,placed.pokemonId());check(m.privateView(p).discard().containsAll(selected),"Cara Liss lost selected physical card identities");
    }}
    static void knockout(){for(UUID p:List.of(A,B)){var m=fixture(IDS.getFirst());if(p.equals(B))m.endTurn(A);UUID other=p.equals(A)?B:A;var source=hand(m,p,"trainer");m.playTrainer(p,source.instanceId(),null);UUID fossil=m.benchPokemonView(p).getLast().pokemonId();m.switchActiveByEffect(p,p,fossil);int prizes=m.privateView(other).prizes().size();m.endTurn(p);m.attack(other,"hit");NonPokemonBatch2Test.settle(m);check(m.privateView(p).discard().contains(source)&&m.privateView(other).prizes().size()==prizes-1,"Rare Fossil KO did not award one Prize");}}
}
